  where g.date < archive_selftest.competitor_compact_from()
  union all
  -- override-only rows on hot/compact dates (no base row)
  select o.date,
         o.isrc,
         o.streams_cumulative_override as streams_cumulative,
         null::bigint as source_run_id,
         null::timestamptz as base_created_at,
         true as is_manual_override,
         o.id as override_id,
         o.note as manual_note,
         o.created_at as manual_created_at,
         o.created_by as manual_created_by
  from competitor.track_daily_stream_overrides o
  where o.date >= archive_selftest.competitor_compact_from()
    and not exists (select 1 from competitor.track_daily_streams t
                    where t.date = o.date and t.isrc = o.isrc and t.date >= competitor.stream_history_hot_from())
    and not exists (select 1 from archive_selftest.competitor_compact m
                    where m.isrc = o.isrc and m.month = date_trunc('month', o.date)::date
                      and m.month < competitor.stream_history_hot_from()
                      and m.vals[extract(day from o.date)::int] is not null)
  union all
  -- DB overrides on archived dates with no archived row at all (hashed key lookup; evaluated only if such rows exist)
  select o.date,
         o.isrc,
         o.streams_cumulative_override as streams_cumulative,
         null::bigint as source_run_id,
         null::timestamptz as base_created_at,
         true as is_manual_override,
         o.id as override_id,
         o.note as manual_note,
         o.created_at as manual_created_at,
         o.created_by as manual_created_by
  from competitor.track_daily_stream_overrides o
  where o.date < archive_selftest.competitor_compact_from()
    and (o.date, o.isrc) not in (select ops.iso_date(r.d), r.isrc from archive_selftest.competitor_rows r);
